// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address actor, uint8 fundAmount) public {
        vm.assume(actor != address(this));
        vm.assume(fundAmount > 0);
        vm.deal(address(c), fundAmount);
        vm.prank(actor);
        bool ok;
        try c.withdrawAll(actor) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
